class Solution:
    def waysToPartition(self, nums: List[int], k: int) -> int:
        def count(arr):
            total = sum(arr)
            pref = res = 0
            for x in arr[:-1]:
                pref += x
                if 2 * pref == total:
                    res += 1
            return res

        ans = count(nums)
        for i in range(len(nums)):
            old = nums[i]
            nums[i] = k
            ans = max(ans, count(nums))
            nums[i] = old
        return ans

