class Solution {
public:
    int waysToPartition(vector<int>& nums, int k) {
        int n = nums.size();
        auto count = [&]() {
            long long total = accumulate(nums.begin(), nums.end(), 0LL), pref = 0;
            int res = 0;
            for (int i = 0; i + 1 < n; i++) {
                pref += nums[i];
                if (2 * pref == total) res++;
            }
            return res;
        };
        int ans = count();
        for (int i = 0; i < n; i++) {
            int old = nums[i];
            nums[i] = k;
            ans = max(ans, count());
            nums[i] = old;
        }
        return ans;
    }
};

