class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length, ans = count(nums);
        for (int i = 0; i < n; i++) {
            int old = nums[i];
            nums[i] = k;
            ans = Math.max(ans, count(nums));
            nums[i] = old;
        }
        return ans;
    }
    private int count(int[] a) {
        long total = 0;
        for (int x : a) total += x;
        long pref = 0;
        int res = 0;
        for (int i = 0; i + 1 < a.length; i++) {
            pref += a[i];
            if (2 * pref == total) res++;
        }
        return res;
    }
}

