    def waysToPartition(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = sum(nums)
        pref = 0
        right = {}
        for p in range(1, n):
            pref += nums[p - 1]
            right[2 * pref] = right.get(2 * pref, 0) + 1
        ans = right.get(2 * total, 0)
        left = {}
        pref = 0
        for i in range(n):
            d = k - nums[i]
            ans = max(ans, right.get(total - d, 0) + left.get(total + d, 0))
            if i + 1 < n:
                pref += nums[i]
                v = 2 * pref
                left[v] = left.get(v, 0) + 1
                right[v] -= 1
        return ans

