class Solution {
public:
    int waysToPartition(vector<int>& nums, int k) {
        int n = nums.size();
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        unordered_map<long long, int> right, left;
        long long pref = 0;
        for (int p = 1; p < n; p++) {
            pref += nums[p - 1];
            right[2 * pref]++;
        }
        int ans = right.count(2 * total) ? right[2 * total] : 0;
        pref = 0;
        for (int i = 0; i < n; i++) {
            long long d = k - nums[i];
            int cur = 0;
            auto it = right.find(total - d);
            if (it != right.end()) cur += it->second;
            it = left.find(total + d);
            if (it != left.end()) cur += it->second;
            ans = max(ans, cur);
            if (i + 1 < n) {
                pref += nums[i];
                left[2 * pref]++;
                right[2 * pref]--;
            }
        }
        return ans;
    }
};

