class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        long total = 0;
        for (int x : nums) total += x;
        Map<Long, Integer> right = new HashMap<>(), left = new HashMap<>();
        long pref = 0;
        for (int p = 1; p < n; p++) {
            pref += nums[p - 1];
            right.merge(2 * pref, 1, Integer::sum);
        }
        int ans = right.getOrDefault(2 * total, 0);
        pref = 0;
        for (int i = 0; i < n; i++) {
            long d = k - nums[i];
            ans = Math.max(ans,
                right.getOrDefault(total - d, 0) + left.getOrDefault(total + d, 0));
            if (i + 1 < n) {
                pref += nums[i];
                left.merge(2 * pref, 1, Integer::sum);
                right.merge(2 * pref, -1, Integer::sum);
            }
        }
        return ans;
    }
}

